#include <iostream>

// Approach 1: Allocates dynamic memory and returns pointer
int* congvt_new(const int* x, const int* y, int n) {
    int* z = new int[n];
    for (int i = 0; i < n; ++i) {
        z[i] = x[i] + y[i];
    }
    return z;
}

// Approach 2: Output parameter for vector addition
void congvt_out(const int* x, const int* y, int* z, int n) {
    for (int i = 0; i < n; ++i) {
        z[i] = x[i] + y[i];
    }
}

// Approach 2 applied to flattened 2D matrix multiplication
void nhanmt(const int* x, const int* y, int* z, int m, int n, int p) {
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < p; ++j) {
            *(z + i * p + j) = 0;
            for (int k = 0; k < n; ++k) {
                *(z + i * p + j) += *(x + i * n + k) * *(y + k * p + j);
            }
        }
    }
}

int main() {
    int n = 3;
    int a[3] = {1, 2, 3};
    int b[3] = {4, 5, 6};
    int c[3] = {0, 0, 0};

    // Test dynamic allocation return
    int* res_heap = congvt_new(a, b, n);
    for (int i = 0; i < n; ++i) {
        std::cout << res_heap[i] << (i + 1 == n ? "\n" : " ");
    }
    delete[] res_heap;

    // Test output parameter
    congvt_out(a, b, c, n);
    for (int i = 0; i < n; ++i) {
        std::cout << c[i] << (i + 1 == n ? "\n" : " ");
    }

    // Test matrix multiplication (2x2 * 2x2)
    int m = 2, k = 2, p = 2;
    int ma[2][2] = {{1, 2}, {3, 4}};
    int mb[2][2] = {{2, 0}, {1, 2}};
    int mc[2][2] = {{0, 0}, {0, 0}};

    nhanmt((int*)ma, (int*)mb, (int*)mc, m, k, p);
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < p; ++j) {
            std::cout << mc[i][j] << (j + 1 == p ? "\n" : " ");
        }
    }

    return 0;
}

#include <iostream>
#include <cstring>

// ho: parameter declared as char hoten[], returns dynamic char*
char* ho(char hoten[]) {
    char* kq = new char[20];
    int i = 0;
    while (hoten[i] != '\0' && hoten[i] != '\40') {
        i++;
    }
    std::strncpy(kq, hoten, i);
    kq[i] = '\0'; // Ensure null-termination
    return kq;
}

// ten: parameter declared as char* hoten, returns dynamic char*
char* ten(char* hoten) {
    char* kq = new char[20];
    int len = static_cast<int>(std::strlen(hoten));
    int i = len;
    while (i > 0 && hoten[i] != '\40') {
        i--;
    }
    int start = (hoten[i] == '\40') ? i + 1 : i;
    int count = len - start;
    std::strncpy(kq, hoten + start, count);
    kq[count] = '\0';
    return kq;
}

// tachht: caller-allocated output parameters, return type void
void tachht(char* hoten, char* ho_out, char* ten_out) {
    int i = 0;
    while (hoten[i] != '\0' && hoten[i] != '\40') {
        i++;
    }
    std::strncpy(ho_out, hoten, i);
    ho_out[i] = '\0';

    int len = static_cast<int>(std::strlen(hoten));
    i = len;
    while (i > 0 && hoten[i] != '\40') {
        i--;
    }
    int start = (hoten[i] == '\40') ? i + 1 : i;
    int count = len - start;
    std::strncpy(ten_out, hoten + start, count);
    ten_out[count] = '\0';
}

int main() {
    char hoten[] = "Nguyen Van An";

    // Test ho()
    char* h = ho(hoten);
    std::cout << "Ho: " << h << "\n";
    delete[] h;

    // Test ten()
    char* t = ten(hoten);
    std::cout << "Ten: " << t << "\n";
    delete[] t;

    // Test tachht()
    char h_buf[20];
    char t_buf[20];
    tachht(hoten, h_buf, t_buf);
    std::cout << "Tach - Ho: " << h_buf << ", Ten: " << t_buf << "\n";

    return 0;
}
